// Differential scenario: the observable behavior of the client-map readers for homes WITHOUT a map, with a version 1
// map and with a version 2 map WITHOUT containers, over a fixed set of repositories. The output is normalized (no
// temp path, no hash) and compared with tests/fixtures/clients-differential.golden.json, which was generated by
// running this very file on the previous candidate (09e9ed9). Fields added later (e.g. BindingInfo.container) are
// deliberately not sampled: the claim is "what existed before reads the same".
import { mkdirSync, mkdtempSync, realpathSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';

const run = (cwd, ...args) => execFileSync('git', ['-C', cwd, ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
const ORIGIN = 'https://git.example.invalid/grupo/api.git';
const sha = value => import('node:crypto').then(({ createHash }) => createHash('sha256').update(value).digest('hex'));
const pool = id => ({ version: 1, policy: 'Fixture', quotaFallback: { enabled: false, optionId: null },
  options: [{ id, provider: 'codex', roles: ['peer'], model: 'model/variant', enabled: true, availability: 'ready', suitableFor: ['coding'], avoidFor: [], notes: 'n' }] });

export async function runScenario(root) {
  const clients = await import(new URL('../../plugin/server/runtime/cli/clients.ts', import.meta.url));
  const routing = await import(new URL('../../plugin/server/runtime/cli/routing.ts', import.meta.url));
  const dir = realpathSync(mkdtempSync(join(tmpdir(), 'slp-diff-')));
  try {
    const repo = (name, { remote = ORIGIN, config = false } = {}) => {
      const path = join(dir, 'repos', name); mkdirSync(path, { recursive: true });
      run(path, 'init', '-q'); run(path, '-c', 'user.name=F', '-c', 'user.email=f@example.invalid', 'commit', '--allow-empty', '-qm', 'base');
      if (remote) run(path, 'remote', 'add', 'origin', remote);
      if (config) { mkdirSync(join(path, '.paseo-slp'), { recursive: true }); writeFileSync(join(path, '.paseo-slp/slp-routing.json'), JSON.stringify(pool('repo-pool'))); writeFileSync(join(path, '.paseo-slp/workspace-protocol.md'), 'Protocol\n'); }
      return path;
    };
    const mapped = repo('mapped'), unmapped = repo('unmapped', { remote: 'https://git.example.invalid/outro/app.git' }), local = repo('local', { config: true }), bare = repo('noremote', { remote: null });
    const wt = join(dir, 'repos', 'mapped-wt'); run(mapped, 'worktree', 'add', '--detach', wt, 'HEAD');
    const plain = join(dir, 'plain'); mkdirSync(plain);
    const sub = join(mapped, 'sub'); mkdirSync(sub);
    const targets = { mapped, unmapped, local, noremote: bare, worktree: wt, plain, subdir: sub, missing: join(dir, 'missing') };
    const common = path => realpathSync(join(path, '.git'));
    const homes = {};
    const mkHome = (name, map) => {
      const home = join(dir, 'homes', name); mkdirSync(join(home, 'slp-clients'), { recursive: true });
      for (const c of ['clienteA']) { const d = join(home, 'slp-clients/clients', c, '.paseo-slp'); mkdirSync(d, { recursive: true }); writeFileSync(join(d, 'slp-routing.json'), JSON.stringify(pool('client-a'))); writeFileSync(join(d, 'workspace-protocol.md'), 'Client protocol\n'); }
      mkdirSync(join(home, 'slp-runtime/state'), { recursive: true }); writeFileSync(join(home, 'slp-runtime/state/peer-pool.json'), JSON.stringify(pool('user-only')));
      if (map !== null) writeFileSync(join(home, 'slp-clients/clients.json'), typeof map === 'string' ? map : JSON.stringify(map));
      homes[name] = home; return home;
    };
    const originHash = await sha(ORIGIN);
    const entries = [{ client: 'ClienteA', project: 'grupo/api', gitCommonDir: common(mapped), originSha256: originHash }, { client: 'ClienteA', project: 'local', gitCommonDir: common(local), originSha256: originHash }];
    const base = { clients: { ClienteA: { directory: 'clienteA' } }, repositories: entries };
    mkHome('none', null);
    mkHome('v1', { version: 1, protectedRoots: [], ...base });
    mkHome('v1-protected', { version: 1, protectedRoots: [join(dir, 'repos')], ...base });
    mkHome('v2-lenient', { version: 2, strict: false, protectedRoots: [], ...base });
    mkHome('invalid', '{ not json');
    const normalize = value => JSON.parse(JSON.stringify(value, (key, v) => typeof v === 'string' ? v.split(dir).join('<T>').replace(/[0-9a-f]{64}/g, '<SHA>').replace(/\b[0-9a-f]{8}\b/g, '<SHA8>') : v));
    const attempt = fn => { try { return { ok: fn() }; } catch (error) { return { error: { code: error.code ?? null, message: error.message } }; } };
    const out = {};
    for (const [homeName, home] of Object.entries(homes)) {
      out[homeName] = { validate: attempt(() => clients.validateClients(home, parsed => routing.validateCatalog(parsed))) };
      for (const [name, path] of Object.entries(targets)) {
        out[homeName][name] = {
          catalog: attempt(() => { const c = routing.readCatalog(path, home); return { scope: c.scope, path: c.path, options: c.options.map(o => o.id), central: c.central ? { client: c.central.client, directory: c.central.directory } : null }; }),
          trace: attempt(() => { const t = clients.traceSourceFor(path, home); return { decidedBy: t.decidedBy, client: t.client ?? null, reason: t.reason, mapPresent: t.mapPresent, linked: t.linked ?? null,
            resolution: t.resolution ? { kind: t.resolution.kind, client: t.resolution.source.client } : null }; }),
          lookup: attempt(() => { const l = clients.lookupClient({ home, cwd: path }); return l.state === 'mapped' ? { state: l.state, client: l.client } : { state: l.state }; }),
        };
      }
    }
    return normalize(out);
  } finally { rmSync(dir, { recursive: true, force: true }); }
}
if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href && process.argv[2] === '--write') {
  const { writeFileSync: write } = await import('node:fs');
  write(process.argv[3], `${JSON.stringify(await runScenario(), null, 1)}\n`);
}
